"""
Context Curation Agent - 2-Phase Path-Based Retrieval

Architecture:
- Phase 1: LLM selects relevant data paths from catalog (~200 tokens)
- Phase 2: Retrieve only selected paths from actual files (~800 tokens)
- Result: 70-90% token reduction vs sending all data
"""

import json
from pathlib import Path
from typing import Any, Dict, List, Optional


# Phase 1: Key Selection Prompt
KEY_SELECTION_PROMPT = """You are a context retrieval specialist. Given a query and a catalog of available data, you select ONLY the specific data paths needed to answer the query.

# Your Task

Analyze the query and data catalog, then return JSON with the exact paths to retrieve.

# Selection Criteria

1. **Direct Relevance**: Only select data directly related to the query
2. **Semantic Matching**: Match on meaning, not just keywords  
3. **Completeness**: Include all necessary context, but nothing extra
4. **Efficiency**: Aim to retrieve <20% of available data

# Output Format

Return ONLY valid JSON:

```json
{
  "retrieve_paths": [
    "phase_evidence:phases[0]",
    "phase_evidence:phases[7]",
    "user_learnings:learnings[0]",
    "document_snapshot:paragraphs[1-5]"
  ],
  "reasoning": "Brief explanation of why these paths were selected"
}
```

# Path Format

- `source_name:path` (e.g., `phase_evidence:phases[0]`)
- Use array indices `[0]`, `[1]`, etc
- Use ranges `[1-5]` for consecutive items
- Use wildcards `[*]` only if truly need all items

**Remember**: Less is more. Be aggressive in filtering.
"""


class ContextCurationAgent:
    """2-phase path-based context curation"""

    def __init__(self):
        pass

    def curate(
        self,
        query: str,
        data_sources: Dict[str, str],  # {name: filepath}
        query_metadata: Optional[Dict] = None,
        llm_service=None,
        provider: str = "openai",  # Prefer OpenAI by default
    ) -> Dict[str, Any]:
        """
        2-phase curation:
        1. Build catalog → LLM selects paths
        2. Retrieve only selected paths

        Args:
            query: The task/question
            data_sources: Dict of {name: filepath}
            query_metadata: Optional metadata
            llm_service: LLM service instance

        Returns:
            Dict with curated_context and stats
        """
        if llm_service is None:
            from clients.llm_service import llm_service as default_llm
            llm_service = default_llm

        try:
            # Phase 1: Build catalog and get path selections
            catalog = self._build_data_catalog(data_sources)
            selected_paths = self._select_paths(query, catalog, query_metadata, llm_service, provider)

            # Phase 2: Retrieve only selected paths
            curated_context = self._retrieve_paths(selected_paths, data_sources)

            # Phase 3: Format into labeled natural language sections
            formatted_context = self._format_context(curated_context)

            # Calculate stats
            original_size = self._estimate_total_size(data_sources)
            curated_size = self._estimate_tokens(curated_context)

            return {
                "curated_context": curated_context,  # Raw JSON for debugging
                "formatted_context": formatted_context,  # Natural language for LLM
                "curation_stats": {
                    "original_token_count": original_size,
                    "curated_token_count": curated_size,
                    "reduction_percentage": round(
                        ((original_size - curated_size) / original_size) * 100, 1
                    ),
                    "paths_selected": len(selected_paths["retrieve_paths"]),
                },
                "reasoning": selected_paths.get("reasoning", ""),
                "selected_paths": selected_paths["retrieve_paths"],
            }

        except Exception as e:
            # Fallback: return empty context on error
            return {
                "curated_context": {},
                "curation_stats": {
                    "original_token_count": 0,
                    "curated_token_count": 0,
                    "reduction_percentage": 0,
                    "paths_selected": 0,
                },
                "reasoning": f"Curation failed: {str(e)}",
                "error": str(e),
            }

    def _build_data_catalog(self, data_sources: Dict[str, str]) -> Dict[str, Any]:
        """
        Scan data files and build rich catalog with metadata

        Returns catalog with retrievable paths and descriptions
        """
        catalog = {}

        for source_name, filepath in data_sources.items():
            try:
                with open(filepath, "r") as f:
                    data = json.load(f)

                if source_name == "phase_evidence":
                    catalog[source_name] = self._catalog_phase_evidence(data, filepath)
                elif source_name == "user_learnings":
                    catalog[source_name] = self._catalog_user_learnings(data, filepath)
                elif source_name == "document_snapshot":
                    catalog[source_name] = self._catalog_document(data, filepath)
                elif source_name == "analysis_context":
                    catalog[source_name] = self._catalog_analysis(data, filepath)
                elif source_name == "comments":
                    catalog[source_name] = self._catalog_comments(data, filepath)
                else:
                    # Generic catalog for unknown types
                    catalog[source_name] = self._catalog_generic(data, filepath)

            except Exception as e:
                # Skip files that can't be read
                continue

        return catalog

    def _catalog_phase_evidence(self, data: Dict, filepath: str) -> Dict:
        """Extract phase names and metadata"""
        items = []
        for phase in data.get("phases", []):
            items.append({
                "path": f"phases[{phase.get('phase_number', 0) - 1}]",
                "label": phase.get("phase_name", "Unknown Phase"),
                "revision_count": phase.get("iteration_context", {}).get("revision_count", 0),
                "size_tokens": self._estimate_tokens(phase),
            })

        return {
            "location": filepath,
            "description": "Writing phase patterns from version history",
            "total_size_tokens": self._estimate_tokens(data),
            "retrievable_items": items,
        }

    def _catalog_user_learnings(self, data: Dict, filepath: str) -> Dict:
        """Extract user learning summaries"""
        items = []
        for idx, learning in enumerate(data.get("learnings", [])):
            items.append({
                "path": f"learnings[{idx}]",
                "label": f"{learning.get('category', 'Unknown')}: {learning.get('actionable_rule', '')[:80]}",
                "category": learning.get("category", ""),
                "subcategory": learning.get("subcategory", ""),
                "size_tokens": self._estimate_tokens(learning),
            })

        # Also include summary rules if present
        if data.get("summary_rules"):
            items.append({
                "path": "summary_rules",
                "label": "Compiled user preference rules",
                "size_tokens": self._estimate_tokens(data["summary_rules"]),
            })

        return {
            "location": filepath,
            "description": "User preferences from comment interactions",
            "total_size_tokens": self._estimate_tokens(data),
            "retrievable_items": items,
        }

    def _catalog_document(self, data: Dict, filepath: str) -> Dict:
        """Catalog document with section grouping"""
        paragraphs = data.get("paragraphs", [])
        items = []

        # Group paragraphs by section (heuristic: empty lines or headers)
        current_section = {"start": 0, "text": ""}
        sections = []

        for idx, para in enumerate(paragraphs):
            text = para.get("text", "").strip()
            if not text or text.isupper() or text.endswith(":"):
                # Section boundary
                if current_section["text"]:
                    sections.append({
                        "start": current_section["start"],
                        "end": idx - 1,
                        "preview": current_section["text"][:100],
                    })
                current_section = {"start": idx, "text": text}
            else:
                current_section["text"] += " " + text

        # Add last section
        if current_section["text"]:
            sections.append({
                "start": current_section["start"],
                "end": len(paragraphs) - 1,
                "preview": current_section["text"][:100],
            })

        # Create retrievable items for sections
        for section in sections:
            if section["start"] == section["end"]:
                path = f"paragraphs[{section['start']}]"
            else:
                path = f"paragraphs[{section['start']}-{section['end']}]"

            items.append({
                "path": path,
                "label": f"Document section: {section['preview'][:50]}...",
                "size_tokens": self._estimate_tokens(
                    paragraphs[section["start"] : section["end"] + 1]
                ),
            })

        return {
            "location": filepath,
            "description": "Current document content",
            "total_size_tokens": self._estimate_tokens(data),
            "retrievable_items": items,
        }

    def _catalog_analysis(self, data: Dict, filepath: str) -> Dict:
        """Catalog analysis context (workflow checkpoints)"""
        items = []

        # Workflow checkpoints (the main content)
        if "workflow_checkpoints" in data:
            items.append({
                "path": "workflow_checkpoints",
                "label": "User's workflow pattern analysis (8 phases)",
                "size_tokens": self._estimate_tokens(data["workflow_checkpoints"]),
            })

        # Analysis ID
        if "analysis_id" in data:
            items.append({
                "path": "analysis_id",
                "label": f"Analysis ID: {data.get('analysis_id', 'Unknown')}",
                "size_tokens": self._estimate_tokens(data.get("analysis_id", "")),
            })

        # User patterns learned (if any)
        if "user_patterns_learned" in data:
            patterns = data["user_patterns_learned"]
            items.append({
                "path": "user_patterns_learned",
                "label": f"User learning patterns ({len(patterns.get('common_struggles', []))} struggles recorded)",
                "size_tokens": self._estimate_tokens(patterns),
            })

        return {
            "location": filepath,
            "description": "Workflow analysis and detected patterns",
            "total_size_tokens": self._estimate_tokens(data),
            "retrievable_items": items,
        }

    def _catalog_comments(self, data: List, filepath: str) -> Dict:
        """Catalog comments with anchor info"""
        items = []
        for idx, comment in enumerate(data):
            anchor = comment.get("target", {})
            items.append({
                "path": f"[{idx}]",
                "label": f"Comment on {anchor.get('anchor_type', 'unknown')}: {comment.get('suggestion', '')[:60]}",
                "anchor_paragraph": anchor.get("approximate_paragraph"),
                "size_tokens": self._estimate_tokens(comment),
            })

        return {
            "location": filepath,
            "description": "AI-generated comments on document",
            "total_size_tokens": self._estimate_tokens(data),
            "retrievable_items": items,
        }

    def _catalog_generic(self, data: Any, filepath: str) -> Dict:
        """Generic catalog for unknown data types"""
        if isinstance(data, dict):
            items = [
                {
                    "path": key,
                    "label": f"Key: {key}",
                    "size_tokens": self._estimate_tokens(value),
                }
                for key, value in data.items()
            ]
        elif isinstance(data, list):
            items = [
                {
                    "path": f"[{idx}]",
                    "label": f"Item {idx}",
                    "size_tokens": self._estimate_tokens(item),
                }
                for idx, item in enumerate(data)
            ]
        else:
            items = []

        return {
            "location": filepath,
            "description": "Data source",
            "total_size_tokens": self._estimate_tokens(data),
            "retrievable_items": items,
        }

    def _select_paths(
        self,
        query: str,
        catalog: Dict,
        query_metadata: Optional[Dict],
        llm_service,
        provider: str = "openai",
    ) -> Dict:
        """Phase 1: LLM selects relevant paths from catalog"""

        # Build selection prompt
        metadata_text = ""
        if query_metadata:
            metadata_text = f"\n\n## Query Metadata\n{json.dumps(query_metadata, indent=2)}"

        catalog_text = json.dumps(catalog, indent=2)

        prompt = f"""{KEY_SELECTION_PROMPT}

# Query
{query}
{metadata_text}

# Available Data Catalog
{catalog_text}

Analyze the query and catalog, then return JSON with the specific paths to retrieve.
"""

        # Debug output: Print full prompt
        print("\n" + "=" * 80)
        print("DEBUG: FULL LLM PROMPT (Phase 1 - Path Selection)")
        print("=" * 80)
        print(prompt)
        print("=" * 80 + "\n")

        # Call LLM with specified provider
        result = llm_service.call_llm(prompt, provider=provider)

        # Debug output: Print LLM response
        print("\n" + "=" * 80)
        print("DEBUG: LLM RESPONSE")
        print("=" * 80)
        print(f"Provider: {result.get('provider', 'unknown')}")
        print(f"Error: {result.get('error', 'None')}")
        print(f"Content:\n{result.get('content', '')}")
        print("=" * 80 + "\n")

        if result.get("error"):
            # Fallback: return empty selection
            return {"retrieve_paths": [], "reasoning": f"Selection failed: {result['error']}"}

        try:
            # Parse LLM response
            selection = json.loads(result["content"].strip())
            return selection
        except json.JSONDecodeError:
            # Fallback: return empty selection
            return {"retrieve_paths": [], "reasoning": "Failed to parse LLM response"}

    def _retrieve_paths(self, selection: Dict, data_sources: Dict[str, str]) -> Dict:
        """Phase 2: Retrieve only selected paths from files"""
        curated = {}

        for path_spec in selection.get("retrieve_paths", []):
            try:
                # Parse path_spec: "source_name:json_path"
                source_name, json_path = path_spec.split(":", 1)

                if source_name not in data_sources:
                    continue

                # Load source data
                with open(data_sources[source_name], "r") as f:
                    data = json.load(f)

                # Extract path
                extracted = self._extract_json_path(data, json_path)

                # Store in curated context
                if source_name not in curated:
                    curated[source_name] = {}
                curated[source_name][json_path] = extracted

            except Exception:
                # Skip paths that can't be retrieved
                continue

        return curated

    def _extract_json_path(self, data: Any, path: str) -> Any:
        """Extract data at JSON path (e.g., 'phases[0]' or 'paragraphs[1-5]')"""
        # Handle simple key access
        if "[" not in path:
            return data.get(path) if isinstance(data, dict) else None

        # Parse path with array access
        parts = path.split("[", 1)
        key = parts[0]
        index_part = parts[1].rstrip("]")

        # Get base object
        obj = data.get(key) if isinstance(data, dict) else data

        if not isinstance(obj, list):
            return obj

        # Handle range [start-end]
        if "-" in index_part:
            start, end = map(int, index_part.split("-"))
            return obj[start : end + 1]

        # Handle wildcard [*]
        if index_part == "*":
            return obj

        # Handle single index [n]
        idx = int(index_part)
        return obj[idx] if idx < len(obj) else None

    def _format_context(self, curated_context: Dict) -> str:
        """Phase 3: Format JSON data into labeled natural language sections"""
        sections = []

        # Format document content
        if "document_snapshot" in curated_context:
            for path, data in curated_context["document_snapshot"].items():
                if "paragraphs" in path:
                    sections.append("## Document Content")
                    if isinstance(data, list):
                        for para in data:
                            text = para.get("text", "").strip()
                            if text:
                                sections.append(text)
                    sections.append("")  # Empty line

        # Format workflow analysis
        if "analysis_context" in curated_context:
            for path, data in curated_context["analysis_context"].items():
                if path == "workflow_checkpoints":
                    sections.append("## User's Workflow Patterns")
                    sections.append(data if isinstance(data, str) else json.dumps(data, indent=2))
                    sections.append("")

        # Format phase evidence
        if "phase_evidence" in curated_context:
            sections.append("## Relevant Writing Phases")
            for path, phase_data in curated_context["phase_evidence"].items():
                if isinstance(phase_data, dict):
                    phase_name = phase_data.get("phase_name", "Unknown Phase")
                    sections.append(f"\n### {phase_name}")
                    sections.append(f"Goal: {phase_data.get('phase_goal', 'N/A')}")
                    sections.append(f"What you do: {phase_data.get('what_user_doing', 'N/A')}")
                    sections.append(f"Common struggles: {phase_data.get('typical_bottlenecks', 'N/A')}")
            sections.append("")

        # Format user learnings
        if "user_learnings" in curated_context:
            sections.append("## User Learning Patterns")
            for path, learning_data in curated_context["user_learnings"].items():
                if isinstance(learning_data, dict):
                    category = learning_data.get("category", "Unknown")
                    rule = learning_data.get("actionable_rule", "")
                    sections.append(f"\n**{category}**: {rule}")
                elif isinstance(learning_data, list):
                    for learning in learning_data:
                        category = learning.get("category", "Unknown")
                        rule = learning.get("actionable_rule", "")
                        sections.append(f"\n**{category}**: {rule}")
            sections.append("")

        return "\n".join(sections)

    def _estimate_tokens(self, data: Any) -> int:
        """Estimate tokens (4 chars ≈ 1 token)"""
        return len(json.dumps(data)) // 4

    def _estimate_total_size(self, data_sources: Dict[str, str]) -> int:
        """Estimate total size of all data sources"""
        total = 0
        for filepath in data_sources.values():
            try:
                with open(filepath, "r") as f:
                    data = json.load(f)
                total += self._estimate_tokens(data)
            except Exception:
                continue
        return total


# Global instance
context_curation_agent = ContextCurationAgent()
